SELECT BOK_DEAL_ACCOUNTING.BOOKSET_ID booksetId, BOK_DEAL_ACCOUNTING.BUSI_NO busiNo, BOK_DEAL_ACCOUNTING.BUSI_TABLE busiTable, TRD_PRODUCT_DEAL.trade_id tradeId, PTL_TRADE.busi_table plBusiTable, PTL_TRADE.PORTFOLIO_ID portfolioId, TRD_FIN_PRODUCT_DEAL_TOTAL.totle_trade_id totleTradeId FROM FIN_PRODUCT INNER JOIN FIN_CASH_INFO ON FIN_PRODUCT.finprod_id = FIN_CASH_INFO.finprod_id AND FIN_CASH_INFO.finprod_type = #{finprodType} AND FIN_CASH_INFO.cash_type_2 = #{cashTypeC02} INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id AND FIN_CASH_PAY_RULE.eff_date < to_date(#{sysDate},'yyyy-MM-dd') AND FIN_CASH_PAY_RULE.pay_cycle = #{BONUS_RULE_07} AND FIN_CASH_PAY_RULE.PAY_TYPE = #{BONUS_MODE_02} INNER JOIN ( select FIN_CASH_PAY_RULE.cash_id, MAX(FIN_CASH_PAY_RULE.eff_date) max_eff_date from FIN_CASH_PAY_RULE where FIN_CASH_PAY_RULE.eff_date < to_date(#{sysDate},'yyyy-MM-dd') group by FIN_CASH_PAY_RULE.cash_id )t2 ON FIN_CASH_PAY_RULE.cash_id = t2.cash_id AND FIN_CASH_PAY_RULE.eff_date = t2.max_eff_date INNER JOIN TRD_PRODUCT_DEAL ON TRD_PRODUCT_DEAL.finprod_id = FIN_PRODUCT.finprod_id AND TRD_PRODUCT_DEAL.busi_type = #{BUSI_TYPE_21} AND TRD_PRODUCT_DEAL.finprod_type2 = #{FINPROD_TYPE_TG_F16} AND TRD_PRODUCT_DEAL.ps = #{PS_C10} AND TRD_PRODUCT_DEAL.TRADE_DATE = to_date(#{sysDate},'yyyy-MM-dd') INNER JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.trade_id = TRD_PRODUCT_DEAL_ADD.trade_id AND TRD_PRODUCT_DEAL_ADD.gen_type = #{CREATE_TYPE_03} INNER JOIN TRD_FIN_PRODUCT_DEAL_TOTAL ON TRD_FIN_PRODUCT_DEAL_TOTAL.totle_trade_id = TRD_PRODUCT_DEAL.TOTLE_TRADE_ID INNER JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL ON PA_TRD_FIN_PRODUCT_DEAL_TOTAL.totle_trade_id = TRD_FIN_PRODUCT_DEAL_TOTAL.totle_trade_id INNER JOIN PTL_TRADE ON PTL_TRADE.busi_no = TRD_FIN_PRODUCT_DEAL_TOTAL.totle_trade_id INNER JOIN BOK_DEAL_ACCOUNTING ON TRD_PRODUCT_DEAL.trade_id = BOK_DEAL_ACCOUNTING.busi_no AND BOK_DEAL_ACCOUNTING.busi_table = #{BUSI_TABLE_02} INNER JOIN BOK_DEAL_ACCOUNTING_DETAIL ON BOK_DEAL_ACCOUNTING_DETAIL.busi_no = BOK_DEAL_ACCOUNTING.busi_no AND BOK_DEAL_ACCOUNTING_DETAIL.busi_table = BOK_DEAL_ACCOUNTING.busi_table WHERE FIN_PRODUCT.profit_type = #{PROFIT_TYPE_03}
AND FIN_PRODUCT.finprod_id IN
#{item}

SELECT FP.FINPROD_ID FROM FIN_PRODUCT FP
AND (FP.finprod_id IN
null) OR FP.finprod_id in (
#{item}
AND NOT EXISTS ( SELECT 1 FROM FIN_PRODUCT INNER JOIN FIN_CASH_INFO ON FIN_PRODUCT.finprod_id = FIN_CASH_INFO.finprod_id AND FIN_CASH_INFO.finprod_type = '01' AND FIN_CASH_INFO.cash_type_2 = 'C01' INNER JOIN FIN_OPEN_RULE ON FIN_OPEN_RULE.cash_id = FIN_CASH_INFO.cash_id
AND (FIN_PRODUCT.finprod_id IN
null) OR FIN_PRODUCT.finprod_id in (
#{item,jdbcType = VARCHAR}
AND CALENDAR_ID in
#{item,jdbcType = VARCHAR}
AND FIN_OPEN_RULE.OPEN_MODE ='02' AND FP.FINPROD_ID = FIN_PRODUCT.finprod_id
)

select to_char(CDATE, 'yyyy-MM-dd') as "holiDate", CALENDAR_ID as "calendarID" from MST_HOLIDAY where IS_HOLIDAY > 0
and CDATE >= #{startDate, jdbcType=DATE}
and CDATE <= #{endDate, jdbcType=DATE}
